// Checks every design in community/ and writes src/generated/community.js for the site.
// Run through `npm run catalog`, which also runs this; CI fails if a design has a problem or the
// generated file is out of date. Each problem is explained in plain words.
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { checkAll, LIMITS } from '../src/engines/community.js';
import { pinOrder } from '../src/engines/export.js';

const root = fileURLToPath(new URL('..', import.meta.url));
export const OUT_COMMUNITY = 'src/generated/community.js';

export function loadDesigns() {
  const dir = root + 'community/';
  if (!existsSync(dir)) return { list: [], problems: [] };
  const list = [], problems = [];
  for (const slug of readdirSync(dir, { withFileTypes: true }).filter(e => e.isDirectory()).map(e => e.name).sort()) {
    const f = dir + slug + '/design.json';
    if (!existsSync(f)) { problems.push('community/' + slug + ': add a design.json (see community/README.md)'); continue; }
    try { list.push({ ...JSON.parse(readFileSync(f, 'utf8')), slug }); } catch (e) { problems.push('community/' + slug + '/design.json is not valid JSON: ' + e.message); }
  }
  return { list, problems };
}

export function buildCommunity() {
  const { list, problems: loadP } = loadDesigns();
  const { designs, problems, cells } = checkAll(list);
  const rows = designs.map((x, k) => {
    const s = x.r.spec, p = pinOrder(s);
    return { sel: k, slug: x.d.slug, title: x.d.title, author: x.d.author, description: x.d.description || '', added: x.d.added || '', project: x.d.project || null, seq: !!s.seq, ins: p.ins, outs: p.outs, ...x.r.stats, code: x.d.code, ...(x.d.tests ? { tests: x.d.tests } : {}) };
  });
  const text = '/* Generated by scripts/community.mjs from community/ (run: npm run catalog). Do not edit. */\n' +
    'export const LIMITS = ' + JSON.stringify(LIMITS) + ';\n' +
    'export const CELLS = ' + cells + ';\n' +
    'export const COMMUNITY = [\n' + rows.map(r => '  ' + JSON.stringify(r)).join(',\n') + '\n];\n';
  return { outputs: { [OUT_COMMUNITY]: text }, problems: loadP.concat(problems.map(p => 'community/' + p)) };
}
